        # default — preserves "no regression with flag OFF" from the brief.
        if expected.get("zone_detection_enabled"):
            env = os.environ.get("LLMTRACE_ZONE_DETECTION_ENABLED", "").lower()
            if env not in ("1", "true", "yes"):
